'use strict';

/**
 * Assembles a request path from URL fragments and environment origin data.
 */
export class PathAssembler {
  constructor() {
    this.pathSeparator = '/';
    // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
    // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
    // by any combination of letters, digits, plus, period, or hyphen.
    this.schemeRelativePattern = /^([a-z][a-z\d+\-.]*:)?\/\//i;
  }

  buildFullPath(request, protocol, joinContext, origin) {
    const requestedURL = request.requestedURL;
    const baseURL = request.baseURL;
    const source = protocol.raw != null ? protocol.raw : requestedURL;
    const isAbsolute = this.schemeRelativePattern.test(source) &&
      this.schemeRelativePattern.test(origin.href);

    if (baseURL && !isAbsolute) {
      return joinContext.relativeURL
        ? joinContext.normalizedBase + this.pathSeparator + joinContext.normalizedRelative
        : joinContext.baseURL;
    }

    return requestedURL;
  }
}

/**
 * Determines whether the specified URL is absolute
 *
 * @param {string} url The URL to test
 *
 * @returns {boolean} True if the specified URL is absolute, otherwise false
 */
export default function isAbsoluteURL(url) {
  return new PathAssembler().schemeRelativePattern.test(url);
}
'use strict';

import { ProtocolDescriptor } from './parseProtocol.js';
import { LocationOrigin } from '../platform/index.js';

/**
 * Holds the base and requested URL for a path assembly operation.
 */
export class URLRequest {
  constructor(baseURL, requestedURL) {
    this.baseURL = baseURL;
    this.requestedURL = requestedURL;
  }
}

/**
 * Holds the fragments used to join a base URL with a relative URL.
 */
export class URLJoinContext {
  constructor(baseURL, relativeURL) {
    this.baseURL = baseURL;
    this.relativeURL = relativeURL;
  }

  get normalizedBase() {
    return this.baseURL.replace(/\/?\/$/, '');
  }

  get normalizedRelative() {
    return this.relativeURL.replace(/^\/+/, '');
  }
}

/**
 * Builds the URL objects consumed by path assembly.
 *
 * @param {string} baseURL The base URL
 * @param {string} requestedURL The requested URL
 *
 * @returns {{request: URLRequest, protocol: ProtocolDescriptor, joinContext: URLJoinContext, origin: LocationOrigin}}
 */
export function createPathContext(baseURL, requestedURL) {
  return {
    request: new URLRequest(baseURL, requestedURL),
    protocol: new ProtocolDescriptor(requestedURL),
    joinContext: new URLJoinContext(baseURL, requestedURL),
    origin: new LocationOrigin()
  };
}

/**
 * Creates a new URL by combining the specified URLs
 *
 * @param {string} baseURL The base URL
 * @param {string} relativeURL The relative URL
 *
 * @returns {string} The combined URL
 */
export default function combineURLs(baseURL, relativeURL) {
  return relativeURL
    ? baseURL.replace(/\/?\/$/, '') + '/' + relativeURL.replace(/^\/+/, '')
    : baseURL;
}

